CREATE OR REPLACE FUNCTION public.fn_cashier_recipient_wallet_balances(p_club_id uuid, p_user_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor uuid:=auth.uid(); actor_role text;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'Not Authenticated' USING ERRCODE='42501'; END IF;
 actor_role:=public.fn_club_bank_role(p_club_id);
 IF actor_role IS NULL OR actor_role NOT IN ('owner','co_owner','admin','super_agent','agent','sub_agent') THEN RAISE EXCEPTION 'Cashier Access Is Required' USING ERRCODE='42501'; END IF;
 IF p_user_ids IS NULL OR cardinality(p_user_ids)>25 OR EXISTS(SELECT 1 FROM unnest(p_user_ids) u WHERE u IS NULL) THEN RAISE EXCEPTION 'Choose At Most 25 Recipients' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(p_user_ids) u WHERE u<>actor AND NOT public.fn_club_cashier_can_transact(p_club_id,actor,u)) THEN RAISE EXCEPTION 'That Member Is Not In Your Downline' USING ERRCODE='42501'; END IF;
 RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',cm.user_id,
  'player_wallet',CASE WHEN cm.role<>'admin' THEN coalesce(cm.chip_balance,0) END,
  'agent_wallet',CASE WHEN cm.role IN ('owner','co_owner','admin','super_agent','agent','sub_agent') THEN coalesce(a.agent_wallet_balance,0) END,
  'promo_wallet',CASE WHEN cm.role IN ('owner','co_owner','admin','super_agent','agent','sub_agent') THEN coalesce(a.promo_wallet_balance,0) END)), '[]'::jsonb)
  FROM public.club_members cm LEFT JOIN public.agents a ON a.club_id=cm.club_id AND a.user_id=cm.user_id
  WHERE cm.club_id=p_club_id AND cm.user_id=ANY(p_user_ids) AND coalesce(cm.status,'active') IN ('active','approved'));
END
$function$

CREATE OR REPLACE FUNCTION public.fn_is_platform_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  SELECT role INTO v_role FROM public.profiles WHERE id = auth.uid();
  RETURN v_role IN ('admin', 'superadmin', 'god');
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_player_spendable_balance(p_user_id uuid, p_club_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_club uuid := NULL;
  v_club_name text := NULL;
  v_balance numeric := 0;
  v_source text := 'club_chips';
  v_paying uuid := NULL;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( p_user_id IS DISTINCT FROM auth.uid() AND NOT EXISTS (SELECT 1 FROM club_members cm                   WHERE cm.user_id = p_user_id                     AND cm.agent_id = auth.uid()) AND NOT EXISTS (SELECT 1 FROM club_members cm2                   JOIN union_clubs uc ON uc.club_id = cm2.club_id                   WHERE cm2.user_id = p_user_id                     AND public.fn_is_union_overseer(uc.union_id, auth.uid())))) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('balance', 0, 'source', 'none', 'club_id', NULL, 'club_name', NULL);
  END IF;

  IF p_table_id IS NOT NULL THEN
    -- Seated or sitting down: the seat's own club is the wallet that will be
    -- debited by a rebuy or add-on.
    SELECT ts.club_id INTO v_club
      FROM table_seats ts
     WHERE ts.table_id = p_table_id AND ts.user_id = p_user_id AND ts.left_at IS NULL
     LIMIT 1;
    IF v_club IS NULL THEN
      v_club := public.fn_seat_club_for_user(p_user_id, p_table_id, p_club_id);
      -- THE SHEET SHOWS THE WALLET THE BUY-IN WILL SPEND (2026-10-12). When
      -- the default member club cannot cover this table's minimum and another
      -- of the player's clubs in the union can, atomic_table_buyin spends that
      -- one (fn_ca_cash_paying_club), so the balance shown is that one too.
      v_paying := public.fn_ca_cash_paying_club(
        p_user_id, p_table_id, p_club_id,
        public.fn_ca_cash_entry_need(p_user_id, p_table_id));
      IF v_paying IS NOT NULL THEN
        v_club := v_paying;
      END IF;
    END IF;
  ELSIF p_tournament_id IS NOT NULL THEN
    -- THE DISPLAY READS THE DEBIT'S RESOLVER (2026-09-13). A tournament entry
    -- is stamped (fn_stamp_entry_club) and charged (atomic_deduct_wallet_and_log
    -- from fn_register_for_tournament, which declares no app.ledger_club_id) by
    -- fn_tournament_club_for_user(user, tournament, NULL): the tournament's own
    -- club for a club event, and for a union-hosted event the player's OLDEST
    -- member club in the union. The preferred club is NULL here for the same
    -- reason it is NULL there - the registration path passes none - so the
    -- wallet this returns is the wallet the entry leaves. Passing p_club_id
    -- (tournaments.club_id, the union's house club) instead resolved to the
    -- house-club wallet, which is not the one charged. Verified against Dan's
    -- own Lunch Rush entry: stamped and debited Club JAQK, shown 'Midway Union'.
    --
    -- 2026-10-12: the registration doors now pay from the member club that
    -- can cover the entry when the default one cannot (fn_ca_entry_paying_club),
    -- so the Sign Up card reads that wallet first.
    v_club := COALESCE(
      public.fn_ca_entry_paying_club(p_user_id, p_tournament_id),
      public.fn_tournament_club_for_user(p_user_id, p_tournament_id, NULL));
  ELSIF p_club_id IS NOT NULL THEN
    SELECT m.club_id INTO v_club
      FROM club_members m
     WHERE m.user_id = p_user_id AND m.club_id = p_club_id
     LIMIT 1;
  END IF;

  IF v_club IS NULL THEN
    v_club := public.fn_player_home_club(p_user_id, p_club_hint => NULL);
  END IF;

  IF v_club IS NOT NULL THEN
    SELECT COALESCE(chip_balance, 0) INTO v_balance
      FROM club_members WHERE user_id = p_user_id AND club_id = v_club;
    SELECT c.name INTO v_club_name FROM clubs c WHERE c.id = v_club;
  ELSE
    -- No club anywhere: a pure smarter.poker user, whose only wallet is global.
    SELECT COALESCE(balance, 0) INTO v_balance
      FROM wallets WHERE user_id = p_user_id AND wallet_type = 'PLAYER';
    v_source := 'smarter_poker_wallet';
  END IF;

  RETURN jsonb_build_object(
    'balance', COALESCE(v_balance, 0),
    'source', v_source,
    'club_id', v_club,
    'club_name', v_club_name,
    'club_scoped', true
  );
END $function$

CREATE OR REPLACE FUNCTION public.get_my_full_profile()
 RETURNS SETOF profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.profiles WHERE id = v_uid LIMIT 1;
END;
$function$

CREATE OR REPLACE FUNCTION public.ca_club_operations_overview(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role              text;
  v_platform          boolean;
  v_internal          boolean;
  v_staff             boolean;
  v_finance           boolean;
  v_control           boolean;
  v_name              text;
  v_slug              text;
  v_treasury          numeric;
  v_locked            boolean;
  v_members           bigint;
  v_pending           bigint;
  v_new7              bigint;
  v_member_chips      numeric;
  v_online            bigint;
  v_seated            bigint;
  v_live_tables       bigint;
  v_running_tables    bigint;
  v_waiting_tables    bigint;
  v_reg_tourneys      bigint;
  v_run_tourneys      bigint;
  v_hands_today       bigint := 0;
  v_rake_today        numeric := 0;
  v_reports           bigint;
  v_disputes          bigint;
  v_disputes_aged     bigint;
  v_blacklist         bigint;
  v_blacklist_expired bigint;
  v_chip_requests     bigint;
  v_cashouts          bigint;
  v_credit            bigint;
  v_invoices          bigint;
  v_invoices_overdue  bigint;
  v_tickets           bigint;
  v_flags             bigint;
  v_alerts            jsonb := '[]'::jsonb;
  v_kpis              jsonb;
BEGIN
  IF p_club_id IS NULL THEN
    RAISE EXCEPTION 'a club id is required' USING ERRCODE = '22004';
  END IF;

  SELECT c.name, c.slug, coalesce(c.chip_treasury, 0), coalesce(c.settlement_locked, false)
    INTO v_name, v_slug, v_treasury, v_locked
    FROM clubs c
   WHERE c.id = p_club_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'club not found' USING ERRCODE = 'P0002';
  END IF;

  v_internal := session_user IN ('postgres', 'supabase_admin')
             OR coalesce(auth.role(), '') = 'service_role';
  v_platform := coalesce(fn_is_platform_admin(), false);
  v_role     := coalesce(fn_club_bank_role(p_club_id), '');

  v_staff := v_internal OR v_platform
             OR v_role IN ('owner', 'co_owner', 'admin');

  IF NOT v_staff THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  v_finance := v_internal OR v_platform
               OR v_role IN ('owner', 'co_owner', 'admin');
  v_control := v_internal OR v_platform
               OR v_role IN ('owner', 'co_owner', 'admin');

  SELECT count(DISTINCT cm.user_id) FILTER (
           WHERE coalesce(cm.status, 'approved') IN ('active', 'approved')
             AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = cm.user_id AND pr.status = 'deleted')),
         count(*) FILTER (WHERE cm.status = 'pending'),
         count(DISTINCT cm.user_id) FILTER (
           WHERE cm.created_at > now() - interval '7 days'
             AND coalesce(cm.status, 'approved') IN ('active', 'approved')
             AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = cm.user_id AND pr.status = 'deleted')),
         coalesce(sum(cm.chip_balance) FILTER (
           WHERE coalesce(cm.status, 'active') NOT IN ('banned', 'suspended')), 0)
    INTO v_members, v_pending, v_new7, v_member_chips
    FROM club_members cm
   WHERE cm.club_id = p_club_id;

  SELECT count(*) FILTER (WHERE t.status IN ('running', 'waiting', 'active')),
         count(*) FILTER (WHERE t.status = 'running'),
         count(*) FILTER (WHERE t.status = 'waiting')
    INTO v_live_tables, v_running_tables, v_waiting_tables
    FROM tables t
   WHERE t.club_id = p_club_id;

  SELECT count(DISTINCT ts.user_id)
    INTO v_seated
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
   WHERE (t.club_id = p_club_id OR ts.club_id = p_club_id)
     AND ts.left_at IS NULL
     AND ts.user_id IS NOT NULL
     AND t.status IN ('running', 'waiting')
     AND EXISTS (SELECT 1 FROM club_members cm
                  WHERE cm.club_id = p_club_id AND cm.user_id = ts.user_id
                    AND coalesce(cm.status, 'approved') IN ('active', 'approved'))
     AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = ts.user_id AND pr.status = 'deleted');

  SELECT count(*)
    INTO v_online
    FROM (
      SELECT ts.user_id
        FROM table_seats ts
        JOIN tables t ON t.id = ts.table_id
       WHERE (t.club_id = p_club_id OR ts.club_id = p_club_id)
         AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
         AND t.status IN ('running', 'waiting')
         AND EXISTS (SELECT 1 FROM club_members cm
                      WHERE cm.club_id = p_club_id AND cm.user_id = ts.user_id
                        AND coalesce(cm.status, 'approved') IN ('active', 'approved'))
         AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = ts.user_id AND pr.status = 'deleted')
      UNION
      SELECT cm.user_id
        FROM club_members cm
       WHERE cm.club_id = p_club_id
         AND coalesce(cm.status, 'approved') IN ('active', 'approved')
         AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = cm.user_id AND pr.status = 'deleted')
         AND EXISTS (SELECT 1 FROM public.profiles pp WHERE pp.id = cm.user_id AND coalesce(pp.is_online, false) AND pp.last_seen > now() - interval '5 minutes')
    ) x;

  SELECT count(*) FILTER (WHERE tr.status = 'REGISTERING'),
         count(*) FILTER (WHERE tr.status IN ('RUNNING', 'COMPLETING'))
    INTO v_reg_tourneys, v_run_tourneys
    FROM tournaments tr
   WHERE tr.club_id = p_club_id
     AND tr.status IN ('REGISTERING', 'RUNNING', 'COMPLETING');

  SELECT coalesce((
           SELECT d.hands FROM club_hand_daily d
            WHERE d.club_id = p_club_id
              AND d.stat_date = (now() AT TIME ZONE 'UTC')::date), 0),
         coalesce((
           SELECT d.rake FROM ca_club_rake_daily d
            WHERE d.club_id = p_club_id
              AND d.stat_date = (now() AT TIME ZONE 'UTC')::date), 0)
    INTO v_hands_today, v_rake_today;

  SELECT count(*)
    INTO v_reports
    FROM user_reports r
   WHERE coalesce(r.status, 'pending') = 'pending'
     AND EXISTS (SELECT 1 FROM club_members m
                  WHERE m.club_id = p_club_id AND m.user_id = r.reported_user_id);

  SELECT count(*), count(*) FILTER (WHERE d.created_at < now() - interval '72 hours')
    INTO v_disputes, v_disputes_aged
    FROM disputes d
   WHERE d.club_id = p_club_id
     AND coalesce(d.status, 'open') IN ('open', 'under_review', 'escalated');

  SELECT count(*) FILTER (WHERE b.expires_at IS NULL OR b.expires_at > now()),
         count(*) FILTER (WHERE b.expires_at IS NOT NULL AND b.expires_at <= now())
    INTO v_blacklist, v_blacklist_expired
    FROM blacklists b
   WHERE b.club_id = p_club_id;

  SELECT count(*)
    INTO v_chip_requests
    FROM chip_requests q
   WHERE q.club_id = p_club_id AND coalesce(q.status, 'pending') = 'pending';

  SELECT count(*)
    INTO v_cashouts
    FROM cashout_requests q
   WHERE q.club_id = p_club_id
     AND q.completed_at IS NULL
     AND q.cancelled_at IS NULL
     AND coalesce(q.status, 'pending') NOT IN ('completed', 'cancelled', 'rejected', 'failed');

  SELECT count(*)
    INTO v_credit
    FROM credit_requests q
   WHERE q.club_id = p_club_id AND coalesce(q.status, 'pending') = 'pending';

  SELECT count(*), count(*) FILTER (WHERE i.due_at IS NOT NULL AND i.due_at < now())
    INTO v_invoices, v_invoices_overdue
    FROM settlement_invoices i
   WHERE i.club_id = p_club_id
     AND coalesce(i.status, 'generated') NOT IN ('paid', 'settled', 'cancelled', 'void');

  SELECT count(*)
    INTO v_tickets
    FROM tournament_tickets tk
   WHERE tk.club_id = p_club_id
     AND tk.redeemed_at IS NULL
     AND tk.cancelled_at IS NULL
     AND coalesce(tk.status, 'issued') NOT IN ('redeemed', 'cancelled', 'expired');

  SELECT count(*)
    INTO v_flags
    FROM anti_cheat_flags f
   WHERE coalesce(f.status, 'open') = 'open'
     AND (f.club_id = p_club_id OR
          (f.club_id IS NULL AND EXISTS (
             SELECT 1 FROM club_members cm
              WHERE cm.club_id = p_club_id AND cm.user_id = f.player_id)));

  IF v_finance AND v_invoices_overdue > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'invoices-overdue', 'severity', 'critical', 'tool', 'settlement',
      'title', 'Invoices Past Due', 'count', v_invoices_overdue));
  END IF;

  IF v_disputes_aged > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'disputes-aged', 'severity', 'critical', 'tool', 'disputes',
      'title', 'Disputes Past Seventy Two Hours', 'count', v_disputes_aged));
  ELSIF v_disputes > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'disputes-open', 'severity', 'warning', 'tool', 'disputes',
      'title', 'Disputes Open', 'count', v_disputes));
  END IF;

  IF v_chip_requests > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'chip-requests', 'severity', 'warning', 'tool', 'cashier',
      'title', 'Chip Requests Waiting', 'count', v_chip_requests));
  END IF;

  IF v_cashouts > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'cashouts', 'severity', 'warning', 'tool', 'cashier',
      'title', 'Cash Out Requests Waiting', 'count', v_cashouts));
  END IF;

  IF v_credit > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'credit-requests', 'severity', 'warning', 'tool', 'cashier',
      'title', 'Credit Requests Waiting', 'count', v_credit));
  END IF;

  IF v_pending > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'join-requests', 'severity', 'warning', 'tool', 'players',
      'title', 'Membership Requests Waiting', 'count', v_pending));
  END IF;

  IF v_reports > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'reports-open', 'severity', 'warning', 'tool', 'reports',
      'title', 'Player Reports To Review', 'count', v_reports));
  END IF;

  IF v_flags > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'anti-cheat-flags', 'severity', 'warning', 'tool', 'anti-cheat',
      'title', 'Integrity Flags Open', 'count', v_flags));
  END IF;

  IF v_finance AND v_treasury <= 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'club-bank-empty', 'severity', 'warning', 'tool', 'cashier',
      'title', 'The Club Bank Is Empty', 'count', 0));
  END IF;

  IF v_locked THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'settlement-locked', 'severity', 'info', 'tool', 'settlement',
      'title', 'Settlement Is Locked', 'count', 0));
  END IF;

  IF v_blacklist_expired > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'blacklist-expired', 'severity', 'info', 'tool', 'blacklist',
      'title', 'Expired Exclusions To Clear', 'count', v_blacklist_expired));
  END IF;

  v_kpis := jsonb_build_object(
    'members', v_members,
    'members_pending', v_pending,
    'members_new_7d', v_new7,
    'online_now', v_online,
    'seated_now', v_seated,
    'live_tables', v_live_tables,
    'running_tables', v_running_tables,
    'waiting_tables', v_waiting_tables,
    'tournaments_registering', v_reg_tourneys,
    'tournaments_running', v_run_tourneys,
    'hands_today', v_hands_today);

  IF v_finance THEN
    v_kpis := v_kpis || jsonb_build_object(
      'rake_today', v_rake_today,
      'club_bank', v_treasury,
      'member_chips', v_member_chips);
  END IF;

  RETURN jsonb_build_object(
    'generated_at', now(),
    'club', jsonb_build_object('id', p_club_id, 'name', v_name, 'slug', v_slug),
    'viewer', jsonb_build_object(
      'role', nullif(v_role, ''),
      'is_platform_staff', v_platform,
      'can_view_finance', v_finance,
      'can_control_club', v_control),
    'kpis', v_kpis,
    'counts', jsonb_build_object(
      'members', v_members,
      'members_pending', v_pending,
      'reports_open', v_reports,
      'disputes_open', v_disputes,
      'disputes_aged', v_disputes_aged,
      'blacklist_active', v_blacklist,
      'blacklist_expired', v_blacklist_expired,
      'chip_requests_pending', v_chip_requests,
      'cashouts_pending', v_cashouts,
      'credit_requests_pending', v_credit,
      'invoices_open', CASE WHEN v_finance THEN v_invoices ELSE NULL END,
      'invoices_overdue', CASE WHEN v_finance THEN v_invoices_overdue ELSE NULL END,
      'tickets_outstanding', v_tickets,
      'anti_cheat_flags_open', v_flags),
    'alerts', v_alerts,
    'settlement_locked', v_locked);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_cash_entry_need(p_user_id uuid, p_table_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_min numeric;
  v_max numeric;
  v_tournament uuid;
  v_need numeric;
BEGIN
  SELECT t.min_buy_in, t.max_buy_in, t.tournament_id
    INTO v_min, v_max, v_tournament
    FROM public.tables t WHERE t.id = p_table_id;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;
  v_need := COALESCE(v_min, 0);
  IF v_tournament IS NULL AND p_user_id IS NOT NULL THEN
    v_need := GREATEST(v_need, COALESCE(public.fn_cash_rejoin_floor(p_user_id, p_table_id), 0));
  END IF;
  IF v_max IS NOT NULL AND v_max > 0 THEN
    v_need := LEAST(v_need, v_max);
  END IF;
  RETURN GREATEST(v_need, 0);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_cash_paying_club(p_user_id uuid, p_table_id uuid, p_preferred_club uuid, p_amount numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_union uuid;
  v_default uuid;
  v_balance numeric;
BEGIN
  IF p_user_id IS NULL OR p_table_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN NULL;
  END IF;

  SELECT t.union_id INTO v_union
    FROM public.tables t
    JOIN public.clubs c ON c.id = t.club_id
   WHERE t.id = p_table_id
     AND t.tournament_id IS NULL
     AND c.asset IS DISTINCT FROM 'diamonds';
  IF v_union IS NULL THEN
    RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.table_seats ts
      JOIN public.tables t2 ON t2.id = ts.table_id
     WHERE ts.user_id = p_user_id AND ts.left_at IS NULL AND ts.club_id IS NOT NULL
       AND t2.union_id = v_union
       AND lower(coalesce(t2.status, '')) NOT IN ('closed','completed','cancelled','finished')
  ) THEN
    RETURN NULL;
  END IF;

  v_default := public.fn_seat_club_for_user(p_user_id, p_table_id, p_preferred_club);
  IF v_default IS NOT NULL THEN
    SELECT m.chip_balance INTO v_balance
      FROM public.club_members m
     WHERE m.user_id = p_user_id AND m.club_id = v_default
       AND m.status IN ('active', 'approved');
    IF COALESCE(v_balance, 0) >= p_amount THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN public.fn_ca_union_wallet_that_can_pay(p_user_id, v_union, p_amount);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_entry_paying_club(p_user_id uuid, p_tournament_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t record;
  v_charge numeric;
  v_default uuid;
  v_balance numeric;
BEGIN
  IF p_user_id IS NULL OR p_tournament_id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT t.union_id, t.buy_in_amount, t.buy_in_fee, t.bounty_amount,
         (COALESCE(t.is_bounty, false) OR COALESCE(t.is_pko, false)
          OR COALESCE(t.is_mystery_bounty, false)) AS is_bounty
    INTO v_t
    FROM public.tournaments t WHERE t.id = p_tournament_id;
  IF NOT FOUND OR v_t.union_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF public.fn_ca_tournament_unit_cents(p_tournament_id) = 100 THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id AND tp.user_id = p_user_id) THEN
    RETURN NULL;
  END IF;

  SELECT s.charge INTO v_charge
    FROM public.fn_tournament_entry_split(
      v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount, v_t.is_bounty) s;
  IF v_charge IS NULL OR v_charge <= 0 THEN
    RETURN NULL;
  END IF;

  v_default := public.fn_tournament_club_for_user(p_user_id, p_tournament_id, NULL);
  IF v_default IS NOT NULL THEN
    SELECT m.chip_balance INTO v_balance
      FROM public.club_members m
     WHERE m.user_id = p_user_id AND m.club_id = v_default
       AND m.status IN ('active', 'approved');
    IF COALESCE(v_balance, 0) >= v_charge THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN public.fn_ca_union_wallet_that_can_pay(p_user_id, v_t.union_id, v_charge);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_player_home_club(p_user_id uuid, p_club_hint uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_club uuid;
BEGIN
  IF p_user_id IS NULL THEN RETURN NULL; END IF;
  IF p_club_hint IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.user_id = p_user_id AND cm.club_id = p_club_hint
       AND cm.status IN ('active','approved')
  ) THEN RETURN p_club_hint; END IF;
  SELECT cm.club_id INTO v_club
    FROM public.club_members cm
   WHERE cm.user_id = p_user_id AND cm.status IN ('active','approved')
   ORDER BY cm.joined_at ASC NULLS LAST, cm.club_id
   LIMIT 1;
  RETURN v_club;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_poker_arena_context(p_club_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_club public.clubs%ROWTYPE; v_role text; v_member boolean;
BEGIN
  IF v_uid IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_uid) THEN
    RAISE EXCEPTION 'Authentication Required' USING ERRCODE = '28000';
  END IF;
  SELECT c.* INTO v_club FROM public.clubs c
  WHERE c.id::text = btrim(p_club_key) OR c.club_id::text = btrim(p_club_key)
     OR lower(c.slug) = lower(btrim(p_club_key))
  ORDER BY (c.id::text = btrim(p_club_key)) DESC LIMIT 1;
  IF NOT FOUND OR v_club.lifecycle_status = 'retired' THEN RETURN NULL; END IF;
  IF v_club.asset = 'diamonds' THEN
    IF v_club.is_platform IS DISTINCT FROM true OR v_club.union_id IS NOT NULL
       OR NOT EXISTS (SELECT 1 FROM public.ca_arena_settings WHERE club_id = v_club.id) THEN
      RAISE EXCEPTION 'Invalid Diamond Arena Identity' USING ERRCODE = '23514';
    END IF;
    v_member := true; v_role := 'player';
  ELSIF v_club.asset = 'chips' AND v_club.is_platform = false THEN
    SELECT m.role INTO v_role FROM public.club_members m
      WHERE m.club_id = v_club.id AND m.user_id = v_uid AND m.status IN ('active','approved');
    v_member := FOUND;
  ELSE RAISE EXCEPTION 'Invalid Arena Asset' USING ERRCODE = '23514';
  END IF;
  RETURN jsonb_build_object('arena',jsonb_build_object('id',v_club.id,'asset',v_club.asset,
    'is_platform',v_club.is_platform,'union_id',v_club.union_id), 'member',v_member,'role',v_role,
    'cashGamesEnabled',v_club.asset='diamonds' AND COALESCE(
      (SELECT s.cash_games_enabled FROM public.ca_arena_settings s WHERE s.club_id=v_club.id),false),
    -- DIAMOND PHASE 8: the tournament switch, read the same way.
    'tournamentsEnabled',v_club.asset='diamonds' AND COALESCE(
      (SELECT s.tournaments_enabled FROM public.ca_arena_settings s WHERE s.club_id=v_club.id),false));
END $function$

CREATE OR REPLACE FUNCTION public.fn_seat_club_for_user(p_user_id uuid, p_table_id uuid, p_preferred_club uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_union uuid; v_table_club uuid;
BEGIN
  SELECT t.union_id, t.club_id INTO v_union, v_table_club
    FROM public.tables t WHERE t.id = p_table_id;
  -- A DIAMOND TOURNAMENT CHAIR SITS IN THE ARENA (2026-09-29). A Diamond
  -- chair's money is custody held by the arena, and the deferred seat guard
  -- (zzz_diamond_seat_keeps_custody: P0812 and its cash arm) matches that
  -- custody to the chair's club at COMMIT. Diamond membership is automatic
  -- and has no club_members row, so the lookups below never find the arena:
  -- they answered a chip club or none, and every Diamond chair was refused.
  -- A table whose club plays in Diamonds seats every player in that club.
  IF EXISTS (SELECT 1 FROM public.clubs c
              WHERE c.id = v_table_club AND c.asset = 'diamonds') THEN
    RETURN v_table_club;
  END IF;
  IF v_union IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.club_members cm
       WHERE cm.user_id = p_user_id AND cm.club_id = v_table_club
         AND cm.status IN ('active','approved')
    ) THEN RETURN v_table_club; END IF;
    RETURN public.fn_player_home_club(p_user_id, p_preferred_club);
  END IF;
  RETURN public.fn_seat_club_for_user_membership_unchecked(
    p_user_id, p_table_id, p_preferred_club
  );
END;
$function$
